import React, { useState, useEffect, useContext } from 'react';
import EventForm from './EventForm';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Dashboard = () => {
  const [events, setEvents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const { user, logout } = useContext(AuthContext) || {};
  const navigate = useNavigate();

  const fetchEvents = async () => {
    try {
      // Send the logged in user ID to get filtered results
      if (user?._id) {
        const res = await axios.get(`http://localhost:5000/api/events?userId=${user._id}`);
        setEvents(res.data);
      }
    } catch (err) {
      console.error("Error fetching events", err);
    }
  };

  useEffect(() => {
    if (user?._id) {
      fetchEvents();
    }
  }, [user]);

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const styles = {
    container: { minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', padding: '30px 20px', fontFamily: "sans-serif" },
    header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', maxWidth: '1200px', margin: '0 auto 40px', color: 'white' },
    title: { fontSize: '36px', fontWeight: '700' },
    userInfo: { display: 'flex', alignItems: 'center', gap: '20px' },
    logoutBtn: { padding: '10px 20px', backgroundColor: '#f44336', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' },
    content: { maxWidth: '1200px', margin: '0 auto' },
    section: { marginBottom: '40px' },
    sectionTitle: { fontSize: '28px', color: 'white', marginBottom: '20px' },
    formCard: { backgroundColor: 'white', borderRadius: '12px', padding: '30px', boxShadow: '0 10px 40px rgba(0,0,0,0.2)' },
    toggleBtn: { padding: '10px 20px', backgroundColor: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', marginBottom: '20px' },
    eventGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' },
    eventCard: { backgroundColor: 'white', borderRadius: '12px', padding: '20px', borderLeft: '5px solid #667eea' },
    eventTitle: { fontSize: '22px', fontWeight: '700', color: '#333', marginBottom: '10px' },
    eventInfo: { color: '#666', fontSize: '14px', marginBottom: '8px' },
    badge: { fontSize: '12px', padding: '4px 8px', borderRadius: '4px', backgroundColor: '#eee', display: 'inline-block', marginBottom: '10px' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>📊 Dashboard</h1>
        <div style={styles.userInfo}>
          {user && <span>👋 Welcome, {user.name}!</span>}
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </div>

      <div style={styles.content}>
        <div style={styles.section}>
          <h2 style={styles.sectionTitle}>✨ Create a New Event</h2>
          <div style={styles.formCard}>
            {!showForm ? (
              <button style={styles.toggleBtn} onClick={() => setShowForm(true)}>+ Add New Event</button>
            ) : (
              <>
                <button style={{ ...styles.toggleBtn, backgroundColor: '#888' }} onClick={() => setShowForm(false)}>✕ Close</button>
                <EventForm
                  currentUserId={user?._id}
                  onEventCreated={() => { fetchEvents(); setShowForm(false); }}
                />
              </>
            )}
          </div>
        </div>

        <div style={styles.section}>
          <h2 style={styles.sectionTitle}>🎉 Your Events</h2>
          <div style={styles.eventGrid}>
            {events.map(event => (
              <div key={event._id} style={styles.eventCard}>
                <div style={styles.badge}>
                  {event.creator?._id === user?._id ? "⭐ You Organized" : "📩 Invited"}
                </div>
                <h3 style={styles.eventTitle}>🎊 {event.name}</h3>
                <p style={styles.eventInfo}>📅 {new Date(event.date).toLocaleDateString()}</p>
                <p style={styles.eventInfo}>📍 {event.location}</p>
                <p style={styles.eventInfo}>👥 Attendees: {event.attendees?.length || 0}</p>
                <div style={{ color: '#667eea', fontWeight: 'bold', cursor: 'pointer' }}>View Details →</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
